// GradientBackground — "Portfolio 1", made with the 21st.dev Gradient
// Builder and exported as live CSS (the builder's own Copy-CSS background,
// plus its soften-blur and grain passes). Zero dependencies: one <div> that
// fills its parent. Drop it behind your content:
// <div className="relative h-96"><GradientBackground className="absolute inset-0" /></div>
// Remix the source recipe (colors, mode, finish) in the editor:
// https://21st.dev/community/gradients/editor?from=fa055ceb-c780-409a-ae72-fdc368a5bc01
export function GradientBackground({ className }: { className?: string }) {
  return (
    <div
      aria-hidden="true"
      className={className}
      style={{
        position: "relative",
        overflow: "hidden",
        width: "100%",
        height: "100%",
        containerType: "size",
      }}
    >
      <div
        style={{
          position: "absolute",
        inset: 0,
        backgroundColor: "#1B1740",
        backgroundImage:
          "url(\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='120' height='120'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)' opacity='0.005'/></svg>\"), radial-gradient(circle at 50% 50%, rgba(0, 0, 0, 0) 52%, rgba(0, 0, 0, 0.05600000000000001) 100%), radial-gradient(150% 53.2% at 51.7% 6%, rgba(247, 243, 255, 0.92) 0%, rgba(247, 243, 255, 0.7764800000000001) 14.75%, rgba(247, 243, 255, 0.46) 29.5%, rgba(247, 243, 255, 0.14352) 44.25%, rgba(247, 243, 255, 0) 59%), radial-gradient(150% 53.2% at 51.27% 31%, rgba(155, 184, 240, 0.92) 0%, rgba(155, 184, 240, 0.7764800000000001) 14.75%, rgba(155, 184, 240, 0.46) 29.5%, rgba(155, 184, 240, 0.14352) 44.25%, rgba(155, 184, 240, 0) 59%), radial-gradient(150% 53.2% at 43.4% 72%, rgba(94, 92, 192, 0.92) 0%, rgba(94, 92, 192, 0.7764800000000001) 14.75%, rgba(94, 92, 192, 0.46) 29.5%, rgba(94, 92, 192, 0.14352) 44.25%, rgba(94, 92, 192, 0) 59%), radial-gradient(150% 53.2% at 51.57% 94%, rgba(27, 23, 64, 0.92) 0%, rgba(27, 23, 64, 0.7764800000000001) 14.75%, rgba(27, 23, 64, 0.46) 29.5%, rgba(27, 23, 64, 0.14352) 44.25%, rgba(27, 23, 64, 0) 59%)",
        backgroundSize: "120px 120px, auto, auto, auto, auto, auto",
        backgroundBlendMode: "overlay, normal, normal, normal, normal, normal",
        }}
      />
      <svg
        aria-hidden="true"
        style={{
          position: "absolute",
          inset: 0,
          width: "100%",
          height: "100%",
          opacity: 0.005,
          mixBlendMode: "overlay",
        }}
      >
        <filter id="grain-fa055ceb">
          <feTurbulence
            type="fractalNoise"
            baseFrequency="0.8"
            numOctaves="2"
            stitchTiles="stitch"
          />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter="url(#grain-fa055ceb)" />
      </svg>
    </div>
  )
}

